    /// <summary>Returns the demo copy of an attachment.</summary>
    public static async Task<string> CopyAttachmentAsync(AttachmentInfo att, string targetDir)
    {
        var src = Path.Combine(AppPaths.Root, "demo-files", att.FileName);
        if (!File.Exists(src)) throw new FileNotFoundException(att.FileName);
        Directory.CreateDirectory(targetDir);
        var dest = AttachmentFiles.PathFor(targetDir, att);
        await using (var i = File.OpenRead(src)) await AttachmentFiles.WriteAsync(dest, s => i.CopyToAsync(s), default);
        return dest;
    }
